const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const projectId = String(payload.projectId || payload.id || 'prj-client').trim();
const contractId = String(payload.contractId || `LIT-SLA-${projectId.toUpperCase()}`).trim();
const clientName = String(payload.clientName || payload.client || 'Client Partner').trim();
const clientEmail = String(payload.clientEmail || payload.email || '').trim().toLowerCase();
const slaTier = String(payload.slaTier || payload.tier || 'PREMIUM_ENTERPRISE').toUpperCase();
const contractEndDate = String(payload.contractEndDate || payload.expiryDate || new Date(Date.now() + 15 * 86400000).toISOString());

const now = Date.now();
const expiryTime = new Date(contractEndDate).getTime();
const daysRemaining = Math.max(0, Math.ceil((expiryTime - now) / (1000 * 60 * 60 * 24)));

let urgencyLevel = 'STANDARD_NOTICE';
if (daysRemaining <= 5) {
  urgencyLevel = 'CRITICAL_IMMINENT_EXPIRATION';
} else if (daysRemaining <= 15) {
  urgencyLevel = 'RENEWAL_WINDOW_OPEN';
}

const slaMetrics = {
  contractId,
  projectId,
  clientName,
  clientEmail,
  slaTier,
  contractEndDate,
  daysRemaining,
  urgencyLevel,
  uptimeAchievedPastYear: '99.98%',
  totalIncidentsResolved: 4,
  averageResolutionHours: 2.1
};

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    slaMetrics
  }
}];

const item = $input.first().json;
const m = item.slaMetrics;

let monthlyBaseFee = 1500;
if (m.slaTier === 'MISSION_CRITICAL_24_7') monthlyBaseFee = 3500;
else if (m.slaTier === 'STANDARD_BUSINESS') monthlyBaseFee = 750;

const annualBaseFee = monthlyBaseFee * 12;
const annualDiscountPct = 15;
const annualDiscountAmount = Math.round(annualBaseFee * (annualDiscountPct / 100));
const annualFinalPrice = annualBaseFee - annualDiscountAmount;

const invoiceEstimate = {
  invoiceNumber: `INV-RENEW-${m.projectId.toUpperCase()}-${new Date().getFullYear()}`,
  tier: m.slaTier,
  options: {
    annualPlan: {
      billingCadence: 'ANNUAL_UPFRONT',
      baseFeeUSD: annualBaseFee,
      discountPercent: annualDiscountPct,
      discountSavingsUSD: annualDiscountAmount,
      totalUSD: annualFinalPrice,
      benefits: [
        'Guaranteed SLA response times (2h critical, 8h standard)',
        'Monthly security patches & dependency upgrades',
        '24/7 synthetic health monitoring & automatic rollbacks',
        'Dedicated Slack/Teams channel with Vikash Saravanan',
        '15% annual commitment discount applied'
      ]
    },
    monthlyPlan: {
      billingCadence: 'MONTHLY_RETAINER',
      monthlyFeeUSD: monthlyBaseFee,
      totalAnnualizedUSD: annualBaseFee,
      benefits: [
        'Standard SLA response times (6h critical, 24h standard)',
        'Quarterly maintenance and patching review',
        'Business hours support coverage'
      ]
    }
  },
  paymentDueBefore: m.contractEndDate
};

return [{
  json: {
    ...item,
    invoiceEstimate
  }
}];

const item = $input.first().json;
const m = item.slaMetrics;
const inv = item.invoiceEstimate;

const reminderCard = {
  title: `Maintenance & SLA Renewal Notice: ${m.projectId} (${m.daysRemaining} days remaining)`,
  recipient: m.clientEmail || 'finance@logicintelligencetechnologies.com',
  subject: `[LIT Action Required] Maintenance Agreement Renewal for ${m.projectId} - Expires in ${m.daysRemaining} Days`,
  urgency: m.urgencyLevel,
  highlights: [
    `Current SLA Tier: ${m.slaTier}`,
    `Contract End Date: ${m.contractEndDate.split('T')[0]}`,
    `Past Period Uptime: ${m.uptimeAchievedPastYear}`,
    `Annual Renewal Option: $${inv.options.annualPlan.totalUSD}/year (includes $${inv.options.annualPlan.discountSavingsUSD} discount)`
  ],
  renewalPortalReference: `portal.logicintelligencetechnologies.com/billing/renew?contract=${m.contractId}`,
  accountExecutive: 'Vikash Saravanan (Lead System Engineer)',
  dispatchedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'renewal_notice_generated',
    slaMetrics: m,
    invoiceEstimate: inv,
    reminderCard
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'renewal_notice_generated',
  detail: {
    slaMetrics: item.json.slaMetrics,
    invoiceEstimate: item.json.invoiceEstimate,
    reminderCard: item.json.reminderCard
  }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
